import {
  IsBoolean,
  IsInt,
  IsNotEmpty,
  IsNumber,
  IsOptional,
  IsString,
  Min,
} from 'class-validator';
import { Type } from 'class-transformer';

export class CreateProductDto {
  // Generated by the server; any client value is ignored.
  @IsOptional()
  @IsString()
  @IsNotEmpty()
  code?: string;

  @IsOptional()
  @IsString()
  barcode?: string;

  @IsString()
  @IsNotEmpty()
  name: string;

  @IsString()
  @IsNotEmpty()
  categoryId: string;

  @IsString()
  @IsNotEmpty()
  primaryIteamUnitId: string;

  @Type(() => Number)
  @IsInt()
  @IsNotEmpty()
  itemType: number;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  costingMethod?: number;

  @Type(() => Number)
  @IsNumber()
  @Min(0)
  retailPrice: number;

  @Type(() => Number)
  @IsNumber()
  @Min(0)
  wholesalePrice: number;

  @Type(() => Number)
  @IsNumber()
  @Min(0)
  bulkWholesalePrice: number;

  @IsOptional()
  @Type(() => Number)
  @IsNumber()
  @Min(0)
  reorderLimit?: number;

  @IsOptional()
  @IsBoolean()
  hasExpiryDate?: boolean;
}
